insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('48e2051d-9493-5969-a85a-34c1d3d1d2ab', 'back-squat', 'Barbell Back Squat', array['quadriceps', 'glutes']::text[], array['adductors', 'hamstrings', 'spinal erectors', 'core']::text[], array['barbell', 'rack']::text[], 'strength', 'squat', 'compound', 'intermediate', false, false, 'A foundational lower-body lift with the bar resting across the upper back.', array['Set the bar in the rack at mid-chest height and step under it so it rests on your upper traps.', 'Grip the bar just outside shoulder width, brace your core and unrack it with both feet.', 'Take two or three steps back and set your feet about shoulder width, toes slightly turned out.', 'Breathe in, brace, and sit down and back between your hips while keeping the bar over mid-foot.', 'Descend to at least thighs parallel (or your controlled depth), then drive up through the whole foot to stand tall.']::text[], array['Knees track over toes', 'Chest proud, ribs down', 'Push the floor away']::text[], array['Heels lifting off the floor', 'Knees caving inward', 'Losing the brace and rounding at the bottom']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c9e047cf-9c77-57d0-be9a-7c74d6ff30d9', 'front-squat', 'Barbell Front Squat', array['quadriceps', 'glutes']::text[], array['upper back', 'core', 'adductors']::text[], array['barbell', 'rack']::text[], 'strength', 'squat', 'compound', 'advanced', false, false, 'A squat with the bar racked on the front of the shoulders, demanding an upright torso.', array['Rack the bar on the front of your shoulders, close to the throat, using a clean grip or crossed arms.', 'Lift your elbows high so your upper arms are close to parallel with the floor.', 'Brace and squat straight down, keeping your torso upright and elbows up.', 'Drive up through mid-foot, leading with the elbows.']::text[], array['Elbows high', 'Sit between the heels', 'Stay tall']::text[], array['Elbows dropping so the bar rolls forward', 'Rounding the upper back', 'Shifting onto the toes']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('ee1fd8c7-c27d-505c-9ae9-8d214fb5f7dd', 'goblet-squat', 'Goblet Squat', array['quadriceps', 'glutes']::text[], array['core', 'upper back']::text[], array['dumbbell', 'kettlebell']::text[], 'strength', 'squat', 'compound', 'beginner', false, false, 'A squat holding one dumbbell or kettlebell at the chest — an excellent way to learn squat mechanics.', array['Hold a dumbbell vertically (or a kettlebell by the horns) against your chest.', 'Stand with feet shoulder width or slightly wider, toes turned out a little.', 'Sit down between your hips, keeping the weight close and your chest up.', 'Pause briefly at the bottom, then stand up by driving through your whole foot.']::text[], array['Elbows inside the knees at the bottom', 'Weight stays glued to the chest', 'Whole-foot pressure']::text[], array['Letting the weight drift away from the body', 'Rising onto the toes', 'Cutting depth short']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('77c79b74-ae46-5017-aada-31057d7f00a8', 'bodyweight-squat', 'Bodyweight Squat', array['quadriceps', 'glutes']::text[], array['core', 'adductors']::text[], array['bodyweight']::text[], 'strength', 'squat', 'compound', 'beginner', false, true, 'An unloaded squat that builds the movement pattern and leg endurance.', array['Stand with feet about shoulder width apart, arms extended forward for balance.', 'Push your hips back and bend your knees to lower as far as you can control.', 'Keep your heels down and chest up.', 'Stand back up and squeeze your glutes at the top.']::text[], array['Sit back and down', 'Heels heavy', 'Knees follow toes']::text[], array['Knees collapsing inward', 'Rounding the lower back', 'Rushing the descent']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('96ec4aa8-76ba-5b56-aef8-60a73dcaa4ec', 'box-squat-to-chair', 'Sit-to-Stand (Chair Squat)', array['quadriceps', 'glutes']::text[], array['core']::text[], array['bodyweight']::text[], 'strength', 'squat', 'compound', 'beginner', false, true, 'A squat to a sturdy chair or box that controls depth — ideal for building confidence and leg strength.', array['Stand in front of a sturdy chair with feet hip to shoulder width apart.', 'Reach your arms forward and slowly sit back until you lightly touch the seat.', 'Without fully relaxing, lean slightly forward and stand back up.', 'Use your hands on your thighs or the armrests for assistance if needed.']::text[], array['Slow on the way down', 'Nose over toes to stand', 'Squeeze glutes at the top']::text[], array['Dropping onto the seat', 'Feet too close to the chair', 'Knees caving in']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f0303216-82cb-5825-b13b-6069891e4291', 'leg-press', 'Leg Press', array['quadriceps', 'glutes']::text[], array['hamstrings', 'adductors']::text[], array['machine']::text[], 'strength', 'squat', 'compound', 'beginner', false, false, 'A machine-based squat pattern that allows heavy leg training with back support.', array['Sit with your back and hips flat against the pad and feet shoulder width on the platform.', 'Release the safety handles and lower the platform by bending your knees under control.', 'Lower until your hips are about to lift off the pad.', 'Press the platform away through your whole foot without locking the knees hard.']::text[], array['Lower back stays on the pad', 'Control the bottom', 'Full-foot pressure']::text[], array['Letting the hips curl off the seat', 'Snapping knees into lockout', 'Using a tiny range of motion']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('5e6bf624-4d33-5f2e-846d-8575e5bb2bd6', 'conventional-deadlift', 'Conventional Deadlift', array['glutes', 'hamstrings', 'spinal erectors']::text[], array['quadriceps', 'lats', 'forearms', 'upper back']::text[], array['barbell']::text[], 'strength', 'hinge', 'compound', 'intermediate', false, false, 'Lifting a loaded barbell from the floor to standing — a cornerstone of strength and powerlifting.', array['Stand with mid-foot under the bar, feet about hip width apart.', 'Hinge down and grip the bar just outside your legs.', 'Bring your shins to the bar, set a flat back and pull the slack out of the bar.', 'Brace and push the floor away, keeping the bar against your legs.', 'Stand tall with hips and knees locked out, then lower the bar under control by hinging first.']::text[], array['Bar stays over mid-foot', 'Chest and hips rise together', 'Lats tight — protect the armpits']::text[], array['Rounding the lower back', 'Jerking the bar off the floor', 'Hyperextending at lockout']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('b21764b9-623b-540c-9329-6ffae8225d72', 'sumo-deadlift', 'Sumo Deadlift', array['glutes', 'adductors', 'quadriceps']::text[], array['hamstrings', 'spinal erectors', 'forearms']::text[], array['barbell']::text[], 'strength', 'hinge', 'compound', 'intermediate', false, false, 'A wide-stance deadlift with hands inside the legs, emphasizing hips and adductors.', array['Take a wide stance with toes turned out and shins close to the bar.', 'Grip the bar with arms straight down inside your knees.', 'Push your knees out over your toes, set your chest up and brace.', 'Spread the floor with your feet and stand up, keeping the bar close.']::text[], array['Knees out', 'Hips close to the bar', 'Spread the floor']::text[], array['Hips shooting up first', 'Knees caving in', 'Stance too wide to control']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c196879d-3bb9-5ea4-bb35-fb9fce076736', 'trap-bar-deadlift', 'Trap Bar Deadlift', array['quadriceps', 'glutes', 'hamstrings']::text[], array['spinal erectors', 'traps', 'forearms']::text[], array['trap_bar']::text[], 'strength', 'hinge', 'compound', 'beginner', false, false, 'A deadlift with a hexagonal bar that keeps the load centred, often easier to learn.', array['Step inside the trap bar with feet hip width apart.', 'Hinge and bend your knees to grip the handles at their centre.', 'Set a flat back, brace and take the slack out.', 'Drive through the floor to stand tall, then lower with control.']::text[], array['Proud chest', 'Push the floor away', 'Stand tall, don''t lean back']::text[], array['Rounding the back', 'Gripping off-centre', 'Leaning back at lockout']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('0e912efb-2839-5f97-b38e-6e57cd1acea7', 'romanian-deadlift', 'Romanian Deadlift', array['hamstrings', 'glutes']::text[], array['spinal erectors', 'forearms']::text[], array['barbell', 'dumbbell']::text[], 'strength', 'hinge', 'compound', 'intermediate', false, false, 'A top-down hinge that trains the hamstrings through a long range of motion.', array['Stand tall holding a barbell or dumbbells in front of your thighs.', 'Soften your knees slightly and push your hips back, sliding the weight down your legs.', 'Lower until you feel a strong hamstring stretch while keeping a neutral spine.', 'Drive your hips forward to return to standing.']::text[], array['Hips back, not down', 'Weight close to legs', 'Neutral neck']::text[], array['Turning it into a squat', 'Rounding the back to reach lower', 'Letting the weight drift forward']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('e0b2fc90-c0ad-5f83-87ef-b5248aa16272', 'single-leg-rdl', 'Single-Leg Romanian Deadlift', array['hamstrings', 'glutes']::text[], array['core', 'foot and ankle stabilizers']::text[], array['dumbbell', 'kettlebell', 'bodyweight']::text[], 'strength', 'hinge', 'compound', 'intermediate', false, false, 'A unilateral hinge that builds hamstring strength and balance.', array['Stand on one leg holding a weight in the opposite hand (or no weight).', 'Hinge at the hip while the free leg extends behind you in line with your torso.', 'Lower until your torso approaches parallel or you feel a strong stretch.', 'Return to standing by driving the hips forward.']::text[], array['Hips square to the floor', 'Long line from head to heel', 'Soft standing knee']::text[], array['Opening the hips toward the ceiling', 'Rounding the back', 'Rushing and losing balance']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('24e7b541-82f9-5fd5-868e-b41dbf27bd7d', 'kettlebell-swing', 'Kettlebell Swing', array['glutes', 'hamstrings']::text[], array['core', 'upper back', 'forearms']::text[], array['kettlebell']::text[], 'conditioning', 'hinge', 'compound', 'intermediate', false, false, 'An explosive hip hinge that builds posterior-chain power and conditioning.', array['Stand with feet slightly wider than hips, kettlebell a foot in front of you.', 'Hinge, grip the handle, and hike the bell back between your legs.', 'Snap your hips forward to stand tall, letting the bell float to about chest height.', 'Let the bell fall back, hinge to receive it, and repeat rhythmically.']::text[], array['Hinge, don''t squat', 'Snap the hips', 'Arms are ropes']::text[], array['Lifting the bell with the arms', 'Squatting the swing', 'Leaning back at the top']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('3a2574a8-d103-5b95-8d45-e08c602e344c', 'hip-thrust', 'Barbell Hip Thrust', array['glutes']::text[], array['hamstrings', 'quadriceps']::text[], array['barbell', 'bench']::text[], 'strength', 'hinge', 'compound', 'intermediate', false, false, 'A loaded bridge with the upper back on a bench, targeting the glutes.', array['Sit on the floor with your upper back against a bench and a padded bar over your hips.', 'Plant your feet about hip width apart so shins are vertical at the top.', 'Tuck your chin, brace and drive through your heels to lift your hips.', 'Squeeze your glutes at the top with ribs down, then lower under control.']::text[], array['Chin tucked, eyes forward', 'Ribs down at the top', 'Drive through heels']::text[], array['Arching the lower back to finish', 'Feet too far or too close', 'Bouncing the reps']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c56b8193-b199-5189-976d-7a5131053cfd', 'glute-bridge', 'Glute Bridge', array['glutes']::text[], array['hamstrings', 'core']::text[], array['bodyweight', 'mat']::text[], 'strength', 'hinge', 'compound', 'beginner', false, true, 'A floor-based hip extension that builds glute strength with minimal equipment.', array['Lie on your back with knees bent and feet flat, hip width apart.', 'Brace your core and press through your heels to lift your hips.', 'Pause at the top with a straight line from shoulders to knees.', 'Lower slowly to the floor.']::text[], array['Squeeze glutes, not lower back', 'Heels down', 'Pause at the top']::text[], array['Over-arching the back', 'Pushing through the toes', 'Rushing the tempo']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
