insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('927ff863-98dd-5423-b57d-086a7d7012ae', 'step-up', 'Step-Up', array['quadriceps', 'glutes']::text[], array['hamstrings', 'calves']::text[], array['box', 'bodyweight', 'dumbbell']::text[], 'strength', 'lunge', 'compound', 'beginner', false, true, 'Stepping onto a box or step, driving through the working leg.', array['Stand facing a sturdy box or step around knee height or lower.', 'Place one whole foot on the box.', 'Drive through that foot to stand on the box, minimizing push from the back leg.', 'Step down with control and repeat.']::text[], array['Whole foot on the box', 'Drive through the heel', 'Lower with control']::text[], array['Box too high', 'Pushing off the floor leg', 'Knee collapsing inward']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c0443b25-7af2-52c2-8108-0db3e6b13309', 'bench-press', 'Barbell Bench Press', array['chest', 'triceps']::text[], array['front deltoids']::text[], array['barbell', 'bench', 'rack']::text[], 'strength', 'horizontal_push', 'compound', 'intermediate', false, false, 'Pressing a barbell from the chest while lying on a bench — a key upper-body strength lift.', array['Lie on the bench with eyes under the bar and feet planted.', 'Grip slightly wider than shoulder width and set your shoulder blades back and down.', 'Unrack and lower the bar under control to the lower chest.', 'Press the bar up and slightly back to lockout over the shoulders.']::text[], array['Shoulder blades pinned', 'Forearms vertical', 'Leg drive into the floor']::text[], array['Bouncing off the chest', 'Flaring elbows to 90 degrees', 'Hips lifting off the bench']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
