insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('db56d2ef-88f2-5d9d-973e-3c508dbbb4d1', 'pike-push-up', 'Pike Push-Up', array['shoulders', 'triceps']::text[], array['upper chest', 'core']::text[], array['bodyweight']::text[], 'strength', 'vertical_push', 'compound', 'intermediate', false, false, 'A bodyweight overhead-pressing variation with hips raised high.', array['Start in a push-up position, then walk your feet in and lift your hips into an inverted V.', 'Bend your elbows to lower the top of your head toward the floor in front of your hands.', 'Press back up to the pike.']::text[], array['Hips high', 'Head forms a triangle with hands', 'Elbows track back']::text[], array['Turning it into a regular push-up', 'Elbows flaring wide', 'Rushing']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('494f0279-472c-5ff3-b82d-623ca56df53e', 'landmine-press', 'Half-Kneeling Landmine Press', array['shoulders', 'upper chest']::text[], array['triceps', 'core', 'serratus']::text[], array['landmine', 'barbell']::text[], 'strength', 'vertical_push', 'compound', 'beginner', false, false, 'A one-arm angled press that is often friendlier on the shoulders than strict overhead pressing.', array['Kneel on one knee with the barbell end at the shoulder on the same side as the down knee.', 'Brace and squeeze the glute of the down leg.', 'Press the bar up and forward until your arm is straight.', 'Lower slowly back to the shoulder.']::text[], array['Reach at the top', 'Ribs down', 'Stay tall']::text[], array['Twisting the torso', 'Leaning back', 'Shrugging']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('e3283099-2ed6-53af-afec-161f048e247b', 'push-press', 'Push Press', array['shoulders', 'triceps']::text[], array['quadriceps', 'glutes', 'core']::text[], array['barbell', 'rack']::text[], 'plyometric', 'power', 'compound', 'advanced', false, false, 'An overhead press driven by a quick dip and leg drive — trains power transfer.', array['Unrack the bar to the front of your shoulders with a firm grip.', 'Dip a few inches by bending the knees, keeping the torso upright.', 'Drive explosively through the legs and press the bar overhead.', 'Lock out, then lower the bar back to the shoulders with control.']::text[], array['Short, straight dip', 'Explode through the heels', 'Finish with arms']::text[], array['Dipping forward onto the toes', 'Dip too deep', 'Pressing before legs finish']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('5c311b4b-5cee-5625-a74c-616c3b682a4e', 'lateral-raise', 'Dumbbell Lateral Raise', array['side deltoids']::text[], array['upper traps']::text[], array['dumbbell', 'cable', 'band']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'Raising light dumbbells out to the sides to train the shoulders.', array['Stand holding light dumbbells at your sides with a slight bend in the elbows.', 'Raise your arms out to the sides until they reach about shoulder height.', 'Pause, then lower slowly.']::text[], array['Lead with the elbows', 'Light weight, strict form', 'Shoulders down']::text[], array['Swinging the torso', 'Shrugging up', 'Going too heavy']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('569de3dd-0e95-5c43-a846-ad519db822bd', 'triceps-pushdown', 'Cable Triceps Pushdown', array['triceps']::text[], '{}'::text[], array['cable', 'band']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'Extending the elbows against a cable or band to isolate the triceps.', array['Attach a rope or bar to a high cable and grip it with elbows at your sides.', 'Extend your elbows to push the handle down until arms are straight.', 'Return slowly until forearms are about parallel to the floor.']::text[], array['Elbows pinned', 'Squeeze at the bottom', 'Control the return']::text[], array['Elbows drifting forward', 'Leaning over the weight', 'Using momentum']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
