insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('17cb02a9-782c-5929-9985-27a2dc6fa7e9', 'face-pull', 'Face Pull', array['rear deltoids', 'upper back']::text[], array['rotator cuff']::text[], array['cable', 'band']::text[], 'strength', 'horizontal_pull', 'isolation', 'beginner', false, false, 'Pulling a rope toward the face with external rotation to train the upper back and shoulders.', array['Set a rope at upper-chest to face height and grip with thumbs toward you.', 'Step back to create tension and stand tall.', 'Pull the rope toward your face, separating your hands and rotating your arms out.', 'Return slowly.']::text[], array['Pull apart', 'Elbows high', 'Pause at the face']::text[], array['Leaning back', 'Going too heavy', 'Shrugging']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
