insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('ac550237-9589-5c4b-8651-7e4f55805b52', 'dumbbell-curl', 'Dumbbell Biceps Curl', array['biceps']::text[], array['forearms']::text[], array['dumbbell', 'band']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'Curling dumbbells to train elbow flexion.', array['Stand with dumbbells at your sides, palms facing forward.', 'Curl the weights up by bending your elbows while keeping them by your sides.', 'Squeeze at the top, then lower slowly.']::text[], array['Elbows still', 'Full extension', 'No swinging']::text[], array['Swinging the torso', 'Elbows drifting forward', 'Half reps']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('0b9297cd-b204-58d8-9344-e1160421220a', 'hammer-curl', 'Hammer Curl', array['brachialis', 'forearms']::text[], array['biceps']::text[], array['dumbbell']::text[], 'strength', 'isolation', 'isolation', 'beginner', false, false, 'A neutral-grip curl that emphasizes the brachialis and forearms, useful for grip-heavy sports.', array['Hold dumbbells at your sides with palms facing each other.', 'Curl the weights up keeping the neutral grip.', 'Lower under control.']::text[], array['Thumbs up', 'Elbows pinned', 'Controlled tempo']::text[], array['Swinging', 'Rotating the wrists', 'Short range']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('5fc3044f-cc7a-53a4-9a5a-20b6a148b84d', 'plank', 'Front Plank', array['core']::text[], array['shoulders', 'glutes']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'compound', 'beginner', true, true, 'Holding a straight-body position on the forearms to build trunk endurance.', array['Place your forearms on the floor with elbows under shoulders.', 'Extend your legs back and lift your hips so your body forms a straight line.', 'Brace your abs and squeeze your glutes.', 'Breathe steadily and hold for the prescribed time.']::text[], array['Squeeze glutes', 'Ribs down', 'Push the floor away']::text[], array['Hips sagging', 'Hips piked high', 'Holding your breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('cd2c9602-80b4-5ccd-a7c6-8fae81822ddf', 'side-plank', 'Side Plank', array['obliques', 'core']::text[], array['glutes', 'shoulders']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'compound', 'beginner', true, true, 'Holding a sideways plank to train lateral trunk stability.', array['Lie on your side with your elbow under your shoulder.', 'Stack your feet (or stagger them, or bend the knees to make it easier).', 'Lift your hips so your body forms a straight line.', 'Hold, then switch sides.']::text[], array['Hips forward and high', 'Shoulder away from ear', 'Long body']::text[], array['Hips sagging', 'Rolling forward', 'Shrugging']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('0776620a-5f8a-5281-af09-10ba8ed6fb7e', 'dead-bug', 'Dead Bug', array['core']::text[], array['hip flexors']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'compound', 'beginner', false, true, 'A controlled anti-extension drill on your back that teaches core bracing.', array['Lie on your back with arms reaching to the ceiling and knees bent 90 degrees above your hips.', 'Press your lower back gently into the floor.', 'Slowly extend one arm overhead and the opposite leg toward the floor.', 'Return and switch sides without losing back contact.']::text[], array['Low back stays down', 'Exhale as you extend', 'Slow and controlled']::text[], array['Arching the lower back', 'Moving too fast', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('16a7773c-217a-58af-805f-5242283617ce', 'bird-dog', 'Bird Dog', array['core', 'glutes']::text[], array['spinal erectors', 'shoulders']::text[], array['bodyweight', 'mat']::text[], 'core', 'core', 'compound', 'beginner', false, true, 'Extending opposite arm and leg from all fours to build trunk control.', array['Start on hands and knees, hands under shoulders and knees under hips.', 'Brace and slowly extend one arm forward and the opposite leg back.', 'Hold briefly without rotating your hips.', 'Return and switch sides.']::text[], array['Hips level', 'Reach long', 'Slow tempo']::text[], array['Arching the back', 'Rotating the hips', 'Rushing']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('984525de-991d-57d6-adce-5330562cc669', 'pallof-press', 'Pallof Press', array['obliques', 'core']::text[], array['shoulders', 'glutes']::text[], array['cable', 'band']::text[], 'core', 'rotation', 'compound', 'beginner', false, true, 'An anti-rotation press that trains the core to resist twisting forces.', array['Anchor a band or cable at chest height and stand side-on to it.', 'Hold the handle at your chest with both hands and step out to create tension.', 'Press your hands straight out in front of you, resisting the pull to rotate.', 'Hold briefly, return to the chest, then switch sides after the set.']::text[], array['Don''t let it turn you', 'Stack ribs over hips', 'Breathe out on the press']::text[], array['Rotating toward the anchor', 'Standing too close', 'Shrugging']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('24b0a926-f849-5907-bdd4-1700b2b3e7f8', 'cable-woodchop', 'Cable Woodchop', array['obliques', 'core']::text[], array['shoulders', 'hips']::text[], array['cable', 'band']::text[], 'core', 'rotation', 'compound', 'intermediate', false, false, 'A diagonal rotational pull that trains force transfer from hips to hands.', array['Set a cable or band high and stand side-on with feet wider than hips.', 'Grab the handle with both hands, arms extended toward the anchor.', 'Rotate through your hips and torso to pull the handle diagonally down and across your body.', 'Return slowly along the same path.']::text[], array['Pivot the back foot', 'Rotate from the hips', 'Arms stay long']::text[], array['Pulling only with the arms', 'Twisting the lower back without hip turn', 'Going too heavy']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c7747f5f-2b16-5d87-81d4-1fabe02b3402', 'hanging-knee-raise', 'Hanging Knee Raise', array['abdominals', 'hip flexors']::text[], array['forearms', 'lats']::text[], array['pull_up_bar']::text[], 'core', 'core', 'compound', 'intermediate', false, false, 'Raising the knees while hanging from a bar to train the abs and grip.', array['Hang from a pull-up bar with an overhand grip and shoulders engaged.', 'Curl your pelvis and lift your knees toward your chest.', 'Lower under control without swinging.']::text[], array['Curl the pelvis up', 'No swinging', 'Slow lowering']::text[], array['Swinging for momentum', 'Only lifting the thighs without pelvic curl', 'Dropping fast']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('052d69a0-c7f2-5f0f-a34d-3f1e0226c21c', 'ab-wheel-rollout', 'Ab Wheel Rollout', array['abdominals']::text[], array['lats', 'shoulders']::text[], array['ab_wheel']::text[], 'core', 'core', 'compound', 'advanced', false, false, 'Rolling a wheel forward from the knees while resisting lower-back arching.', array['Kneel on a mat holding the ab wheel beneath your shoulders.', 'Brace and roll forward slowly, keeping your hips extended.', 'Go only as far as you can without your lower back sagging.', 'Pull back to the start using your abs.']::text[], array['Tuck the pelvis', 'Short range first', 'Lead back with the abs']::text[], array['Lower back arching', 'Going too far too soon', 'Hips leading the return']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f8594286-c16e-5157-b37f-7c0eebc4d36b', 'medicine-ball-rotational-throw', 'Medicine Ball Rotational Throw', array['obliques', 'hips']::text[], array['shoulders', 'core']::text[], array['medicine_ball']::text[], 'plyometric', 'rotation', 'compound', 'intermediate', false, false, 'A side-on explosive throw into a wall that trains rotational power for striking and throwing sports.', array['Stand side-on to a solid wall about an arm''s length away, holding a medicine ball at hip height.', 'Load by rotating the ball away from the wall and shifting weight to your back leg.', 'Rotate explosively through the hips and torso to throw the ball into the wall.', 'Catch the rebound (or let it drop if it doesn''t rebound) and reset each rep.']::text[], array['Hips lead, arms follow', 'Pivot the back foot', 'Throw through the wall']::text[], array['Throwing with the arms only', 'Ball too heavy to move fast', 'Rushing reps without resetting']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('d99fa237-f8e7-5c95-9f1f-f2cc2a21af45', 'farmers-carry', 'Farmer''s Carry', array['forearms', 'traps', 'core']::text[], array['glutes', 'quadriceps', 'upper back']::text[], array['dumbbell', 'kettlebell', 'trap_bar']::text[], 'strength', 'carry', 'compound', 'beginner', true, false, 'Walking while holding heavy weights at your sides — trains grip, posture and work capacity.', array['Deadlift a pair of heavy dumbbells or kettlebells to your sides.', 'Stand tall with shoulders down and back.', 'Walk with short, quick, controlled steps for the prescribed time or distance.', 'Set the weights down with a controlled hinge.']::text[], array['Tall posture', 'Crush the handles', 'Short steps']::text[], array['Leaning to one side', 'Shrugging the shoulders up', 'Long, unstable strides']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('d7b8f8d8-137f-5b57-85ef-c267027ccadb', 'suitcase-carry', 'Suitcase Carry', array['obliques', 'forearms']::text[], array['traps', 'glutes']::text[], array['dumbbell', 'kettlebell']::text[], 'core', 'carry', 'compound', 'beginner', true, false, 'A one-sided carry that challenges your trunk to stay upright.', array['Pick up one heavy dumbbell or kettlebell at your side.', 'Stand tall without leaning toward or away from the weight.', 'Walk for the prescribed time or distance, then switch hands.']::text[], array['Stay level', 'Shoulders even', 'Brace like a plank']::text[], array['Leaning', 'Rushing', 'Letting the weight swing']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c14796ff-1258-52a2-a569-548b263b23d4', 'sandbag-bear-hug-carry', 'Sandbag Bear-Hug Carry', array['upper back', 'core']::text[], array['biceps', 'quadriceps', 'glutes']::text[], array['sandbag']::text[], 'strength', 'carry', 'compound', 'intermediate', true, false, 'Carrying a sandbag hugged against the chest — a strongman and grappling staple.', array['Lift the sandbag from the floor to your chest using a squat and hip extension.', 'Wrap your arms around it and hug it tightly against your torso.', 'Walk for the prescribed time or distance while breathing behind the brace.', 'Set it down by squatting with control.']::text[], array['Hug tight', 'Upper back strong', 'Short breaths behind the brace']::text[], array['Letting the bag slide down', 'Rounding excessively under load', 'Holding your breath the entire carry']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('637be12d-f7d7-531a-b675-4d1ee34230c4', 'sandbag-to-shoulder', 'Sandbag to Shoulder', array['glutes', 'hamstrings', 'upper back']::text[], array['biceps', 'core', 'quadriceps']::text[], array['sandbag']::text[], 'strength', 'power', 'compound', 'advanced', false, false, 'Lifting a sandbag from the floor onto one shoulder — trains odd-object strength.', array['Straddle the sandbag and hinge to grip it underneath.', 'Lap the bag by pulling it onto your thighs as you sit into a squat.', 'Extend your hips explosively and pop the bag up onto one shoulder.', 'Lower it to the floor with control and alternate shoulders.']::text[], array['Lap, then extend', 'Hips drive the bag', 'Alternate sides']::text[], array['Curling the bag with the arms', 'Skipping the lap position', 'Rushing without resetting']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('8ed6334f-9270-52ad-940a-428ade2184ee', 'sled-push', 'Sled Push', array['quadriceps', 'glutes']::text[], array['calves', 'core', 'shoulders']::text[], array['sled']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, true, 'Driving a loaded sled forward — high-output conditioning with no eccentric soreness.', array['Grip the sled handles with arms extended or bent, body leaning forward.', 'Drive through the balls of your feet with powerful, short steps.', 'Keep a straight line from head to heel.', 'Push for the prescribed distance or time.']::text[], array['Low and strong', 'Drive the knees', 'Steady breathing']::text[], array['Standing too upright', 'Overstriding', 'Rounding the back']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('65e83f70-bb2a-539f-a63d-cc815722afff', 'dead-hang', 'Dead Hang', array['forearms', 'grip']::text[], array['lats', 'shoulders']::text[], array['pull_up_bar']::text[], 'strength', 'carry', 'isolation', 'beginner', true, false, 'Hanging from a bar to build grip endurance and decompress the shoulders.', array['Grip the bar overhand with hands shoulder width apart.', 'Lift your feet and hang with your arms straight.', 'Keep the shoulders active (not fully shrugged to your ears).', 'Hold for the prescribed time and step down safely.']::text[], array['Crush the bar', 'Active shoulders', 'Breathe']::text[], array['Dropping off without control', 'Excessive swinging', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('85f75596-8333-52d9-9841-8eb3b5a78e28', 'power-clean', 'Power Clean', array['glutes', 'hamstrings', 'quadriceps', 'traps']::text[], array['upper back', 'calves', 'core']::text[], array['barbell']::text[], 'plyometric', 'power', 'compound', 'advanced', false, false, 'An Olympic-style lift that moves the bar from floor to shoulders explosively. Learn with qualified coaching.', array['Set up like a deadlift with a hook or overhand grip just outside the legs.', 'Lift the bar to mid-thigh with a flat back, keeping it close.', 'Extend hips, knees and ankles explosively, shrugging as the bar rises.', 'Pull yourself under and catch the bar on the front of the shoulders in a partial squat with elbows high.', 'Stand to finish, then lower the bar safely.']::text[], array['Patient off the floor', 'Jump and shrug', 'Fast elbows']::text[], array['Pulling early with the arms', 'Bar swinging away from the body', 'Catching with elbows low']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('70d0d7da-4b27-5741-a362-e32f9f9c97b8', 'box-jump', 'Box Jump', array['quadriceps', 'glutes', 'calves']::text[], array['hamstrings', 'core']::text[], array['box']::text[], 'plyometric', 'power', 'compound', 'intermediate', false, false, 'Jumping onto a box to develop lower-body explosiveness with reduced landing impact.', array['Stand facing a stable box about a foot away.', 'Swing your arms back and dip into a quarter squat.', 'Jump explosively and land softly on the box with both feet, knees tracking over toes.', 'Stand up fully, then step down — don''t jump down.']::text[], array['Land quiet', 'Step down, don''t jump down', 'Quality over height']::text[], array['Box too high', 'Landing with knees caving', 'Rebounding off the floor for reps']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('807a91fa-cc52-5a16-9884-22408919b8b1', 'broad-jump', 'Broad Jump', array['glutes', 'quadriceps', 'hamstrings']::text[], array['calves', 'core']::text[], array['bodyweight']::text[], 'plyometric', 'power', 'compound', 'intermediate', false, false, 'A horizontal jump for distance that builds hip power.', array['Stand with feet hip width apart.', 'Swing your arms back and hinge into a quarter squat.', 'Explode forward, swinging the arms and extending the hips.', 'Land softly in a balanced squat and stick the landing before resetting.']::text[], array['Swing and drive', 'Stick the landing', 'Reset every rep']::text[], array['Landing stiff-legged', 'Knees caving on landing', 'Chaining reps without control']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('06d0cc29-b99b-511c-a7a6-2038c8d54788', 'medicine-ball-slam', 'Medicine Ball Slam', array['lats', 'core', 'shoulders']::text[], array['glutes', 'hip flexors']::text[], array['medicine_ball']::text[], 'conditioning', 'power', 'compound', 'beginner', false, false, 'Lifting a slam ball overhead and throwing it down forcefully — power and conditioning.', array['Hold a slam ball (a non-bouncing medicine ball) at chest height.', 'Reach it overhead, rising onto your toes.', 'Slam it into the floor in front of you, hinging and pulling with the lats.', 'Squat to pick it up and repeat.']::text[], array['Full reach overhead', 'Throw through the floor', 'Hinge to pick up']::text[], array['Using a bouncy ball that rebounds into the face', 'Rounding to pick it up', 'Arm-only throws']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('a9890942-848b-59ac-9fd2-3de4c5f785f0', 'burpee', 'Burpee', array['full body']::text[], array['chest', 'quadriceps', 'core']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'intermediate', false, false, 'A squat-thrust with a push-up and jump — a full-body conditioning staple.', array['From standing, squat and place your hands on the floor.', 'Jump or step your feet back into a plank and lower your chest to the floor.', 'Push up, jump or step your feet back toward your hands.', 'Stand and jump with arms overhead.']::text[], array['Find a steady rhythm', 'Step back to scale', 'Land softly']::text[], array['Sagging hips in the plank', 'Landing heavily', 'Sacrificing form for speed']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('34e245ab-b4e7-5110-a622-6005b9070bba', 'step-back-burpee', 'Step-Back Burpee (No Jump)', array['full body']::text[], array['quadriceps', 'core', 'shoulders']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', false, true, 'A low-impact burpee that steps instead of jumping.', array['From standing, squat down and place hands on the floor.', 'Step one foot back, then the other, into a plank.', 'Step the feet back in one at a time.', 'Stand tall and reach overhead.']::text[], array['Smooth steps', 'Strong plank', 'Steady breathing']::text[], array['Rounding the back', 'Sagging hips', 'Rushing']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('6fedda54-728a-5348-8de6-db334a96966a', 'sprawl', 'Sprawl', array['hips', 'core']::text[], array['chest', 'quadriceps']::text[], array['bodyweight', 'mat']::text[], 'conditioning', 'conditioning', 'compound', 'intermediate', false, false, 'A wrestling defense drill: shooting the legs back and dropping the hips to the mat.', array['Stand in an athletic stance.', 'Drop your hands to the mat and kick your legs back wide.', 'Drive your hips down toward the mat with chest up.', 'Snap your feet back under you and return to stance.']::text[], array['Hips heavy', 'Legs back and wide', 'Back to stance fast']::text[], array['Landing on the knees', 'Piking the hips up', 'Slow recovery to stance']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('761a6fe4-c43a-50cf-9d5e-fedf41329f3b', 'mountain-climber', 'Mountain Climber', array['core', 'hip flexors']::text[], array['shoulders', 'quadriceps']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, false, 'Driving knees toward the chest alternately from a high plank.', array['Start in a high plank with hands under shoulders.', 'Drive one knee toward your chest, then quickly switch legs.', 'Keep hips level and maintain a steady pace.']::text[], array['Shoulders over hands', 'Hips low', 'Quick feet']::text[], array['Hips bouncing up', 'Shoulders drifting behind hands', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('961215a1-9eb9-50a8-9ba5-05ec03bf2ed0', 'bear-crawl', 'Bear Crawl', array['shoulders', 'core']::text[], array['quadriceps', 'hip flexors']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, false, 'Crawling on hands and feet with knees hovering — coordination and conditioning.', array['Start on hands and knees, then lift your knees an inch off the floor.', 'Move opposite hand and foot forward together in small steps.', 'Keep your back flat and hips low.', 'Crawl forward, backward or laterally for the prescribed time.']::text[], array['Knees low', 'Small steps', 'Flat back']::text[], array['Hips high in the air', 'Big, sloppy steps', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('1e65218d-b2f2-58bf-b3fa-59e382b15b76', 'jump-rope', 'Jump Rope', array['calves', 'cardiovascular system']::text[], array['shoulders', 'forearms']::text[], array['jump_rope']::text[], 'cardio', 'conditioning', 'compound', 'beginner', true, false, 'Skipping rope for footwork rhythm and aerobic or interval conditioning.', array['Hold the handles at hip height with elbows close to your sides.', 'Turn the rope with your wrists, not your arms.', 'Jump just high enough to clear the rope, landing softly on the balls of your feet.', 'Keep a relaxed, steady rhythm for the prescribed time.']::text[], array['Small jumps', 'Wrists turn the rope', 'Stay relaxed']::text[], array['Jumping too high', 'Swinging the arms wide', 'Landing flat-footed']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('3596814c-ae30-5e9b-a0f3-079d8687dd96', 'rowing-intervals', 'Rowing Machine', array['cardiovascular system', 'upper back', 'legs']::text[], array['glutes', 'core', 'biceps']::text[], array['rower']::text[], 'cardio', 'conditioning', 'compound', 'beginner', true, true, 'Indoor rowing for aerobic base and intervals with low joint impact.', array['Strap your feet in and grip the handle with arms straight.', 'Drive with the legs first, then swing the torso back slightly, then pull the handle to your lower ribs.', 'Return in reverse order: arms, torso, then legs.', 'Maintain the prescribed pace or effort for the interval.']::text[], array['Legs, body, arms', 'Arms, body, legs on the way back', 'Smooth, powerful strokes']::text[], array['Pulling with arms first', 'Rounding the back', 'Rushing the recovery']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f826d072-40fc-58c6-96c7-6e471df49ded', 'bike-intervals', 'Air / Stationary Bike', array['cardiovascular system', 'quadriceps']::text[], array['glutes', 'hamstrings']::text[], array['bike']::text[], 'cardio', 'conditioning', 'compound', 'beginner', true, true, 'Cycling on an air or stationary bike for steady aerobic work or intervals.', array['Adjust the seat so your knee is slightly bent at the bottom of the pedal stroke.', 'Warm up at an easy pace for a few minutes.', 'Ride at the prescribed effort for each interval, then recover as programmed.']::text[], array['Seat height matters', 'Smooth cadence', 'Breathe rhythmically']::text[], array['Seat too low', 'Starting intervals too hard', 'Skipping the warm-up']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('814f80b6-2f9d-5078-96eb-f07d8ed23949', 'brisk-walk', 'Brisk / Incline Walk', array['cardiovascular system']::text[], array['glutes', 'calves']::text[], array['bodyweight']::text[], 'cardio', 'conditioning', 'compound', 'beginner', true, true, 'Walking at a pace where you can talk in short sentences — a low-impact aerobic foundation.', array['Walk outdoors or on a treadmill at a pace that raises your breathing.', 'Add a gentle incline on a treadmill to increase effort without running.', 'Swing your arms naturally and stand tall.', 'Keep the effort conversational for the prescribed time.']::text[], array['Tall posture', 'Conversational pace', 'Arms swing naturally']::text[], array['Holding treadmill rails', 'Too steep too soon', 'Overstriding']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('a59bbdba-02a5-54f7-b57f-80db7677d4a2', 'shadowboxing', 'Shadowboxing', array['shoulders', 'cardiovascular system']::text[], array['core', 'calves']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, false, 'Throwing punches and moving in stance without a target — builds rhythm, footwork and endurance.', array['Take a boxing stance with hands up guarding your face.', 'Move on the balls of your feet, staying light.', 'Throw straight punches, hooks and uppercuts in combinations without locking the elbows.', 'Mix in defensive movement (slips, rolls) and footwork for each round.']::text[], array['Hands back to guard', 'Exhale on each strike', 'Stay light on your feet']::text[], array['Dropping the hands', 'Hyperextending elbows', 'Standing flat-footed']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('9c86af10-9366-5884-a2b5-da53bc0294ca', 'heavy-bag-rounds', 'Heavy Bag Rounds', array['shoulders', 'core', 'cardiovascular system']::text[], array['chest', 'triceps', 'hips']::text[], array['heavy_bag']::text[], 'conditioning', 'conditioning', 'compound', 'intermediate', true, false, 'Timed rounds of striking a heavy bag. Use hand wraps and gloves.', array['Wrap your hands and put on bag gloves.', 'Take your stance at arm''s length from the bag.', 'Throw combinations with good form, moving around the bag between flurries.', 'Work for the prescribed round time, then rest.']::text[], array['Rotate from the hips', 'Return to guard', 'Pace your output']::text[], array['Punching without wraps/gloves', 'Pushing instead of striking', 'Gassing out in the first minute']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('7579a68a-dd81-5fec-96d3-c1c142c1dbec', 'battle-rope-waves', 'Battle Rope Waves', array['shoulders', 'cardiovascular system']::text[], array['core', 'forearms', 'legs']::text[], array['battle_rope']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, true, 'Creating waves with heavy ropes for upper-body-dominant intervals.', array['Hold one rope end in each hand and stand in a half squat.', 'Alternate raising and lowering your arms quickly to create waves.', 'Keep your core braced and maintain the waves to the anchor.']::text[], array['Athletic stance', 'Fast hands', 'Waves reach the anchor']::text[], array['Standing straight up', 'Tiny waves', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('93d8ff12-fe6c-52ca-95f3-b725628e909f', 'lateral-shuffle', 'Lateral Shuffle', array['glutes', 'adductors']::text[], array['calves', 'quadriceps']::text[], array['bodyweight']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, false, 'Side-to-side athletic shuffling for footwork and change of direction.', array['Get into an athletic stance with knees bent and chest up.', 'Push off your trailing foot to shuffle sideways without crossing your feet.', 'After a few steps, plant and shuffle back the other way.']::text[], array['Stay low', 'Don''t click heels', 'Push, don''t reach']::text[], array['Standing tall', 'Crossing feet', 'Leaning the torso']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('b706c2f6-7278-5ade-9bdf-9a0cc6a7b9e9', 'hip-escape', 'Hip Escape (Shrimp)', array['core', 'hips']::text[], array['obliques', 'glutes']::text[], array['mat']::text[], 'conditioning', 'conditioning', 'compound', 'beginner', true, false, 'A fundamental grappling movement drill: travelling along the mat by moving the hips away.', array['Lie on your back with knees bent and feet on the mat.', 'Push off one foot and turn onto your side, driving your hips backward away from an imaginary opponent.', 'Frame with your hands as your hips move.', 'Return to your back and repeat to the other side, travelling down the mat.']::text[], array['Hips move first', 'Frame with the arms', 'Turn onto the shoulder']::text[], array['Staying flat on the back', 'Pushing only with arms', 'Not turning to the side']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('9e7b9fa4-211b-523f-8dae-959ed5ef72e0', 'cat-cow', 'Cat-Cow', array['spine']::text[], array['core', 'neck']::text[], array['mat']::text[], 'mobility', 'mobility', null, 'beginner', false, true, 'Gently flexing and extending the spine on hands and knees.', array['Start on hands and knees.', 'Inhale as you let your belly drop and lift your chest and tailbone (cow).', 'Exhale as you round your back toward the ceiling and tuck your chin (cat).', 'Move slowly with your breath.']::text[], array['Move with the breath', 'Segment the spine', 'Pain-free range']::text[], array['Rushing', 'Forcing end range', 'Only moving the neck']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('478f8361-bdb3-55ff-b2e3-798cb7a2fcab', 'worlds-greatest-stretch', 'World''s Greatest Stretch', array['hip flexors', 'hamstrings', 'thoracic spine']::text[], array['adductors', 'glutes']::text[], array['bodyweight']::text[], 'mobility', 'mobility', null, 'beginner', false, false, 'A lunge-based flow combining hip, hamstring and upper-back mobility — a great warm-up.', array['Step into a long lunge and place both hands inside the front foot.', 'Drop your inside elbow toward the front foot''s instep.', 'Rotate and reach the same arm to the ceiling, following it with your eyes.', 'Return the hand down, straighten the front leg for a hamstring stretch, then switch sides.']::text[], array['Back leg long', 'Rotate through upper back', 'Breathe out into each position']::text[], array['Rushing', 'Back knee collapsing', 'Forcing range']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('91fd27fe-1075-5ed1-a3c8-de3636a33b50', '90-90-hip-switch', '90/90 Hip Switch', array['hip rotators']::text[], array['glutes', 'adductors']::text[], array['mat']::text[], 'mobility', 'mobility', null, 'beginner', false, true, 'Rotating the hips between internal and external rotation while seated.', array['Sit with both knees bent at about 90 degrees, one leg in front and one to the side.', 'Sit tall, using your hands behind you for support if needed.', 'Rotate both knees to the other side so the legs switch positions.', 'Continue switching slowly and with control.']::text[], array['Sit tall', 'Slow transitions', 'Use hands if needed']::text[], array['Slumping', 'Forcing the knees down', 'Moving quickly']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('4ca92770-cc91-5a2a-828f-01e86dce89fc', 'thoracic-open-book', 'Thoracic Open Book', array['thoracic spine']::text[], array['chest', 'shoulders']::text[], array['mat']::text[], 'mobility', 'mobility', null, 'beginner', false, true, 'A side-lying rotation that improves upper-back mobility.', array['Lie on your side with knees bent to 90 degrees and arms extended in front of you.', 'Keep your knees together and open your top arm across your body like a book.', 'Follow your hand with your eyes and rotate as far as comfortable.', 'Return slowly and repeat, then switch sides.']::text[], array['Knees stay stacked', 'Rotate the rib cage', 'Exhale as you open']::text[], array['Knees lifting apart', 'Forcing the arm to the floor', 'Holding the breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('57fb2ce8-405e-5a57-b3af-60d3e93b5aa2', 'couch-stretch', 'Couch Stretch', array['hip flexors', 'quadriceps']::text[], '{}'::text[], array['mat']::text[], 'mobility', 'mobility', null, 'intermediate', true, false, 'A kneeling hip-flexor and quad stretch with the back foot elevated.', array['Kneel with your back to a couch or wall, placing one shin up against it.', 'Step the other foot forward into a half-kneeling position.', 'Squeeze the glute of the down leg and tuck your pelvis.', 'Hold the stretch, then switch sides. Use a lower elevation if this is intense.']::text[], array['Squeeze the glute', 'Tuck the pelvis', 'Pad the knee']::text[], array['Arching the lower back', 'Going too deep too soon', 'Bare knee on hard floor']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('40d84c3e-5194-5aaa-8ba0-5f74903b28ba', 'supine-hamstring-stretch', 'Supine Hamstring Stretch', array['hamstrings']::text[], array['calves']::text[], array['band', 'mat']::text[], 'mobility', 'mobility', null, 'beginner', true, true, 'Lying on your back and raising a straight leg with a band or towel.', array['Lie on your back and loop a band or towel around one foot.', 'Keep the other leg bent or flat on the floor.', 'Raise the looped leg with a soft knee until you feel a gentle stretch.', 'Hold and breathe, then switch sides.']::text[], array['Gentle tension', 'Hips stay down', 'Breathe slowly']::text[], array['Yanking the leg', 'Lifting the hips', 'Locking the knee hard']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('e14235bb-fe7b-5c34-acea-7d2fe278b788', 'childs-pose', 'Child''s Pose', array['lower back', 'lats']::text[], array['hips', 'shoulders']::text[], array['mat']::text[], 'mobility', 'mobility', null, 'beginner', true, true, 'A restful kneeling stretch for the back, hips and shoulders.', array['Kneel and sit your hips back toward your heels, knees apart as comfortable.', 'Walk your hands forward and rest your forehead on the mat or a pillow.', 'Breathe deeply into your back.']::text[], array['Long exhales', 'Reach through fingertips', 'Support with pillows if needed']::text[], array['Forcing hips down', 'Tensing shoulders', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('01177fed-1cfd-547d-be52-6ff5bc8eedc6', 'ankle-knee-to-wall', 'Knee-to-Wall Ankle Mobility', array['ankles', 'calves']::text[], '{}'::text[], array['bodyweight']::text[], 'mobility', 'mobility', null, 'beginner', false, true, 'Driving the knee toward a wall over the toes to improve ankle dorsiflexion.', array['Face a wall in a half-kneeling or split stance with the front foot a few inches from the wall.', 'Keeping the heel down, drive the front knee forward to touch the wall.', 'Return and repeat, moving the foot back slightly as mobility improves.']::text[], array['Heel stays down', 'Knee tracks over 2nd toe', 'Smooth rocks']::text[], array['Heel lifting', 'Knee collapsing inward', 'Bouncing']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('11200ed2-83d7-5157-ac59-e560dce6c5d5', 'band-pass-through', 'Band Shoulder Pass-Through', array['shoulders', 'chest']::text[], array['upper back']::text[], array['band']::text[], 'mobility', 'mobility', null, 'beginner', false, true, 'Passing a band from in front of the hips to behind the back with straight arms.', array['Hold a light band with a very wide grip in front of your hips.', 'With straight arms, raise the band overhead and behind you as far as comfortable.', 'Reverse the motion to return to the front.', 'Narrow your grip only as comfort allows.']::text[], array['Wide grip', 'Ribs down', 'Pain-free range only']::text[], array['Grip too narrow', 'Arching the back', 'Forcing through pinching']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('f22015a1-4de3-5166-9917-d100a0b70718', 'deep-squat-hold', 'Deep Squat Hold', array['hips', 'ankles']::text[], array['adductors', 'lower back']::text[], array['bodyweight']::text[], 'mobility', 'mobility', null, 'beginner', true, false, 'Resting in the bottom of a squat to improve hip and ankle mobility.', array['Stand with feet slightly wider than shoulders, toes turned out.', 'Sit down into a deep squat, holding onto a post or door frame if needed.', 'Use your elbows to gently press your knees out.', 'Breathe and hold for the prescribed time.']::text[], array['Heels down (elevate if needed)', 'Chest up', 'Relax into it']::text[], array['Forcing past discomfort', 'Heels lifting', 'Rounding hard']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('23f9503b-882b-5ac2-88c9-7542b301ba3c', 'figure-four-stretch', 'Figure-Four Glute Stretch', array['glutes', 'hip rotators']::text[], '{}'::text[], array['mat']::text[], 'mobility', 'mobility', null, 'beginner', true, true, 'Crossing one ankle over the opposite knee to stretch the glutes.', array['Lie on your back with knees bent.', 'Cross one ankle over the opposite thigh.', 'Pull the bottom thigh toward your chest until you feel a stretch in the crossed leg''s glute.', 'Hold, then switch sides. This can also be done seated in a chair.']::text[], array['Flex the top foot', 'Head relaxed', 'Gentle pull']::text[], array['Lifting the head', 'Pulling too hard', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('df7455a7-5c9e-51f7-8ec9-64ebc9b5333d', 'single-leg-balance', 'Single-Leg Balance', array['foot and ankle stabilizers']::text[], array['glutes', 'core']::text[], array['bodyweight']::text[], 'mobility', 'mobility', null, 'beginner', true, true, 'Standing on one leg to train balance — keep a support within reach.', array['Stand next to a counter or wall for safety.', 'Lift one foot slightly off the floor and balance on the other.', 'Use fingertip support as needed, removing it as balance improves.', 'Hold for the prescribed time and switch legs.']::text[], array['Soft standing knee', 'Eyes on a fixed point', 'Support within reach']::text[], array['Locking the knee', 'Holding breath', 'Training without support nearby']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('db7805bc-6353-5b8c-b66c-fbe0d879b23c', 'standing-march', 'Standing March', array['hip flexors', 'core']::text[], array['calves']::text[], array['bodyweight']::text[], 'cardio', 'conditioning', null, 'beginner', true, true, 'Marching in place with alternating knee lifts — gentle cardio and balance work.', array['Stand tall near a support if needed.', 'Lift one knee toward hip height, then lower and lift the other.', 'Swing the arms naturally and keep a steady rhythm.']::text[], array['Tall posture', 'Controlled lifts', 'Steady breathing']::text[], array['Leaning back', 'Stomping', 'Holding breath']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
