insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('f313ae5b-a7ed-507b-af28-7a36ccc3076d', 'foundations-full-body', 'Foundations: Full-Body Strength', 'Three full-body sessions a week to learn the core movement patterns.', 'A gentle, structured entry into strength training. Each session covers a squat, hinge, push, pull and core pattern with dumbbells and bodyweight. You''ll leave every session feeling like you could have done a little more — that''s intentional.', 'd2ffdbb8-dde8-5744-86a5-50f499a01d50', 'beginner', 6, 3, 45, array['general_health', 'build_strength', 'build_muscle', 'lose_fat', 'type:strength', 'type:home']::text[], array['dumbbell', 'bodyweight', 'bench']::text[], 'free', 'When you complete every set at the top of the rep range with good form at or below the target RPE, increase the load by the smallest available increment next session. Week 6 is a lighter consolidation week.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
