insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('a2d73b71-eb6f-5d1d-8d3b-1602ad208feb', 'home-bodyweight-strength', 'Home Strength: Bodyweight Builder', 'No gym needed — progressive bodyweight strength in 30–40 minutes.', 'Built for living rooms, hotel rooms and garages. Progress by adding reps, slowing tempo, and moving to harder variations. Only a mat is required; a resistance band and pull-up bar unlock extra options.', 'a218e28e-c9e8-59ad-afc5-39d0355f9746', 'beginner', 4, 3, 35, array['general_health', 'build_strength', 'lose_fat', 'type:home', 'type:strength']::text[], array['bodyweight', 'mat', 'band']::text[], 'free', 'Add 1–2 reps per set each week. Once you can do the top of every range, slow the lowering phase to 3 seconds or progress the variation (e.g. incline push-up → push-up).', array['3 minutes marching or skipping', 'Cat-cow × 8', 'Bodyweight squats × 10', 'World''s greatest stretch × 2 per side']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
