insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('abbbdf84-f68a-501a-9cce-ae8a07c22833', 'barbell-strength-foundations', 'Barbell Strength: Linear Progression', 'Three barbell sessions a week built on the big compound lifts.', 'A classic approach for newer lifters with access to a barbell: train the main lifts frequently, add weight in small jumps, and recover well. Accessories are kept minimal so the main work stays fresh.', '42a6d9d6-53e5-5755-8274-3a0b73c46fb9', 'beginner', 8, 3, 60, array['build_strength', 'build_muscle', 'type:strength', 'type:powerlifting']::text[], array['barbell', 'rack', 'bench', 'pull_up_bar']::text[], 'plus', 'Add 2.5 kg / 5 lb to upper-body lifts and 2.5–5 kg / 5–10 lb to lower-body lifts each session while all reps are completed at RPE 8 or below. If you miss reps twice in a row on a lift, reduce that lift by 10% and build back up. Week 8 is a deload.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
