insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('89edf3a7-cf49-5b29-b6c9-4926622a474f', 'powerlifting-base-block', 'Powerlifting Base Block', 'Four days of RPE-driven squat, bench and deadlift training.', 'An intermediate block to build strength and technique in the competition lifts. Intensity is autoregulated with RPE so the plan adapts to your day. Includes variation lifts and targeted accessories.', '355ad483-2f7b-50b3-b6ce-6ac1400d6063', 'intermediate', 8, 4, 75, array['build_strength', 'type:powerlifting', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable']::text[], 'plus', 'Target RPE rises by about 0.5 each week (weeks 1–3, then 5–7). Week 4 drops volume slightly. If a top set feels harder than the target RPE, keep the weight and repeat it next week. Week 8 is a deload before re-testing.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
