insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('30de0b65-3c7f-5b18-824b-987f3da90e5a', 'hypertrophy-upper-lower', 'Hypertrophy: Upper / Lower Split', 'Four sessions per week with productive volume for muscle growth.', 'Each muscle group is trained twice a week with a mix of compound and isolation work in moderate rep ranges. Sets are taken close to — but not past — technical failure to balance stimulus and recovery.', '8f19916a-c1e0-5027-887e-6f78ca07b045', 'intermediate', 8, 4, 65, array['build_muscle', 'build_strength', 'type:hypertrophy']::text[], array['barbell', 'dumbbell', 'bench', 'cable', 'machine', 'rack']::text[], 'plus', 'Use double progression: once you hit the top of the rep range on all sets at the target RPE, add load. Weeks 1–3 build volume, week 4 adds one set to the first two exercises, weeks 5–7 push intensity, week 8 deloads.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
