insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('40f2de83-378c-5c4f-8c96-797653644914', 'athletic-power-development', 'Explosive Athletic Power', 'Jump higher, sprint faster, and stay resilient with power-first training.', 'Each session starts with low-volume, high-quality power work while you are fresh, then builds strength and finishes with rotational and single-leg work. Suitable for field and court athletes and anyone who wants to move explosively.', 'f708f087-cda3-534e-bff4-d71485e31190', 'intermediate', 6, 3, 60, array['athletic_performance', 'build_strength', 'type:athletic', 'type:strength']::text[], array['barbell', 'rack', 'box', 'medicine_ball', 'dumbbell', 'kettlebell']::text[], 'plus', 'Keep power work crisp: stop sets when speed drops. Add load to strength lifts using RPE progression. Plyometric contacts increase modestly in weeks 2–5; week 6 deloads.', array['5 minutes easy jump rope, bike or shadowboxing', 'Lateral shuffles × 20 seconds each way', 'World''s greatest stretch × 3 per side', '2 × 10-second build-up efforts at moderate intensity', 'Ankle knee-to-wall × 10 per side']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
