insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('6ca6d0b5-4a66-56c5-8dbd-6de0fdcd2203', 'mma-fight-conditioning', 'MMA Fight Conditioning', 'Strength and energy-system work to support skill training — not replace it.', 'Designed to sit alongside 2–4 skill sessions a week. Day 1 builds strength and power, day 2 develops anaerobic capacity with round-based intervals, and day 3 builds the aerobic base and grappling-specific endurance. Keep the hardest conditioning away from hard sparring days.', '6d7b7a89-48be-5e4d-8177-56b5b31efe3f', 'intermediate', 6, 3, 55, array['combat_sports', 'improve_conditioning', 'athletic_performance', 'type:mma', 'type:athletic', 'type:grappling', 'type:boxing']::text[], array['barbell', 'kettlebell', 'medicine_ball', 'bike', 'jump_rope', 'heavy_bag', 'pull_up_bar', 'mat']::text[], 'plus', 'Intervals progress by adding a round or shortening rest by 10–15 seconds each week while output stays consistent. Strength work follows RPE. Week 6 tapers for a fight or test.', array['5 minutes easy jump rope, bike or shadowboxing', 'Lateral shuffles × 20 seconds each way', 'World''s greatest stretch × 3 per side', '2 × 10-second build-up efforts at moderate intensity']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
