insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('d7e504af-b39e-5a21-8496-9ee968589c81', 'functional-engine', 'Functional Engine', 'Varied mixed-modal workouts that build strength and a big engine.', 'Inspired by functional fitness training: a strength piece followed by a timed conditioning circuit. Scale every movement to keep good form — intensity should never outrun technique.', '30351ab3-3de1-597d-bb50-b0c1579a05b1', 'intermediate', 4, 4, 55, array['improve_conditioning', 'lose_fat', 'general_health', 'type:functional', 'type:cardio', 'type:strength']::text[], array['barbell', 'kettlebell', 'dumbbell', 'rower', 'box', 'pull_up_bar', 'jump_rope', 'medicine_ball']::text[], 'plus', 'Strength pieces follow RPE progression; circuits aim to beat last week''s rounds or time while keeping form.', array['5 minutes easy jump rope, bike or shadowboxing', 'Lateral shuffles × 20 seconds each way', 'World''s greatest stretch × 3 per side', '2 × 10-second build-up efforts at moderate intensity']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
