insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('08b41fbb-65d7-5d6d-b0cd-b6554822306e', 'lean-and-conditioned', 'Lean & Conditioned', 'Strength to protect muscle plus sustainable cardio to support fat loss.', 'Fat loss is driven mainly by a modest, sustainable calorie deficit; this program supports that with resistance training to maintain muscle and a mix of steady and interval cardio. It is not a substitute for medical advice on weight management.', '26f6bdad-c7c6-58a0-a972-c9cce4439a9c', 'beginner', 6, 4, 45, array['lose_fat', 'general_health', 'improve_conditioning', 'type:cardio', 'type:strength', 'type:functional']::text[], array['dumbbell', 'bodyweight', 'bike', 'rower']::text[], 'plus', 'Add 5 minutes to steady cardio sessions every other week, and progress strength lifts with double progression. Week 6 is lighter.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
