insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('3fc9b340-aa87-5b43-b19d-793a2e53bc15', 'active-aging-low-impact', 'Active Aging: Strength & Balance', 'Joint-friendly strength, balance and mobility to keep you capable for life.', 'Low-impact sessions that train the things that matter for everyday independence: getting up from a chair, carrying groceries, climbing stairs and staying steady on your feet. Every exercise can be done next to a sturdy support. If you have a medical condition, check with your healthcare provider before starting a new exercise program.', '5225ea79-fbe6-5abc-819f-3349cce2461e', 'beginner', 6, 3, 35, array['general_health', 'mobility', 'build_strength', 'type:low_impact', 'type:strength', 'type:mobility']::text[], array['bodyweight', 'dumbbell', 'band']::text[], 'free', 'Add reps before adding weight. When an exercise feels easy (RPE 5 or less) at the top of the range for two sessions, add a little resistance or slow down the lowering phase.', array['3–5 minutes standing march or easy walk', 'Cat-cow × 8 slow breaths', 'Sit-to-stand × 5, slow and controlled', 'Arm circles × 10 each direction']::text[], array['Slow walk 2–3 minutes', 'Seated figure-four stretch 30 seconds per side', 'Child''s pose or seated forward reach 45 seconds']::text[], true, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
