insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('33bddf2c-addd-586a-98c6-c1422e158799', 'recovery-deload-week', 'Recovery & Deload Week', 'A planned easy week: lighter loads, mobility and easy cardio.', 'Use this after a hard block or when check-ins show low readiness. Keep loads at roughly 50–60% of normal and stop every set with plenty in reserve. The goal is to leave each session feeling better than when you started.', '93e126f2-1ee0-5555-97ae-5e7a8a4e10d2', 'beginner', 1, 3, 35, array['general_health', 'mobility', 'type:mobility', 'type:low_impact']::text[], array['bodyweight', 'dumbbell', 'band', 'bike']::text[], 'free', 'No progression this week — return to your regular program next week.', array['3–5 minutes standing march or easy walk', 'Cat-cow × 8 slow breaths', 'Sit-to-stand × 5, slow and controlled', 'Arm circles × 10 each direction']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], true, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
