insert into public.content_items (id, kind, title, body, scripture_ref, is_published, published_at) values ('be1dcb04-dda1-5142-85d2-8baedf793198', 'tip', 'Progress in small steps', 'Progressive overload doesn''t have to mean adding weight every session. One more rep, one more set, better technique or a little less rest all count as progress.', null, true, now()) on conflict (id) do update set title = excluded.title, body = excluded.body, scripture_ref = excluded.scripture_ref;
insert into public.content_items (id, kind, title, body, scripture_ref, is_published, published_at) values ('fecb1c09-3e08-595e-8508-2b6b6acb7e93', 'tip', 'What does RPE mean?', 'RPE (rate of perceived exertion) rates how hard a set felt from 1–10. RPE 8 means you could have done about two more reps with good form. It helps your program adapt to good and bad days.', null, true, now()) on conflict (id) do update set title = excluded.title, body = excluded.body, scripture_ref = excluded.scripture_ref;
insert into public.content_items (id, kind, title, body, scripture_ref, is_published, published_at) values ('4fcb7857-e629-5cc1-aef9-a05730b09b5e', 'tip', 'Recovery is part of training', 'Muscles adapt between sessions, not during them. Consistent sleep, enough protein and planned easier weeks help you keep progressing.', null, true, now()) on conflict (id) do update set title = excluded.title, body = excluded.body, scripture_ref = excluded.scripture_ref;
insert into public.content_items (id, kind, title, body, scripture_ref, is_published, published_at) values ('dfec8589-144d-5d0d-be70-434ad6af8bf1', 'devotional', 'The Narrow Gate', 'Jesus contrasts a wide, easy road with a narrow gate that few find. Training teaches a small version of this lesson every day: the comfortable choice is always available, and the better path usually asks for patience and discipline. Today, consider one area where you want to choose the narrow way — not out of guilt, but because it leads to life.', 'Matthew 7:13–14', true, now()) on conflict (id) do update set title = excluded.title, body = excluded.body, scripture_ref = excluded.scripture_ref;
insert into public.content_items (id, kind, title, body, scripture_ref, is_published, published_at) values ('820fd14d-b886-5b81-8b4b-dd476b830011', 'devotional', 'Temperate in All Things', 'Paul uses the athlete as a picture of focused living. Temperance isn''t harsh restriction; it''s ordering our desires toward what matters most. Reflect on how your training, eating and resting could reflect a balanced, grateful life.', '1 Corinthians 9:24–25', true, now()) on conflict (id) do update set title = excluded.title, body = excluded.body, scripture_ref = excluded.scripture_ref;
insert into public.content_items (id, kind, title, body, scripture_ref, is_published, published_at) values ('f5ff72f4-7099-5537-8c93-0c27afba7809', 'devotional', 'Stewarding the Body', 'Seeing the body as something entrusted to us reframes fitness. The aim isn''t comparison or vanity, but faithful care — strength to serve family, community and neighbor.', '1 Corinthians 6:19–20', true, now()) on conflict (id) do update set title = excluded.title, body = excluded.body, scripture_ref = excluded.scripture_ref;
